insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('111-4301-026','111-4301',26,'single_choice','甲簽發記名本票予乙，經乙記名背書予丙，丙遺失後為丁拾得，丁乃於偽造丙之背書後轉讓予戊，戊 再背書讓與己。經執票人己提示退票，己乃起訴請求票款，下列何人應負給付票款之責任？','僅甲、乙兩人要連帶給付票款','甲、乙、戊要連帶給付票款','甲、乙、丙、丁、戊均不需負票據責任','甲、乙、丙、丁、戊均需負連帶給付票款責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('111-4301-027','111-4301',27,'single_choice','甲為支付手機價款，簽發本票給賣方乙，乙再將該本票背書予丙作為清償貨款之用。其後甲發現手機 根本無法使用，本票到期後，丙向甲請求付款。若丙不知甲、乙間之交易情形，下列敘述，何者 正確？','甲應可拒絕付款，因甲具有物的抗辯權，可對抗一切執票人','甲不可拒絕付款，因甲之抗辯權已因本票轉讓而中斷','甲應可拒絕付款，因丙並非甲之交易相對人','甲不可拒絕付款，因甲對乙亦不具有抗辯權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('111-4301-028','111-4301',28,'single_choice','執票人甲持有經付款人乙承兌、背書人丙背書之匯票，該匯票並記載免除作成拒絕證書。後因甲之過 失致匯票已逾到期日4 年仍未提示請求付款。下列敘述，何者正確？','甲對於丙之票據權利不因罹於時效而消滅','甲對於乙之票據權利因罹於時效而消滅','甲對於乙另有利益償還請求權，權利時效期間為3 年','甲對於乙另有利益償還請求權，權利時效期間為1 年','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('111-4301-029','111-4301',29,'single_choice','下列關於票據喪失救濟方式之敘述，何者錯誤？','票據權利人應於提出止付通知後5 日內，向付款人提出已為聲請公示催告之證明','未於期限內聲請公示催告者，止付通知失其效力','公示催告程序開始後，就尚未到期之票據，聲請人得提供擔保，請求給與新票據','業經簽名而未記載完成之空白票據不可向付款人提出止付通知，但得聲請公示催告','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-030','111-4301',30,'single_choice','甲簽發以A 為付款人、乙為受款人之匯票一紙交付予乙，乙再以空白背書方式轉讓予丙，丙未背書 將票據交付予丁，丁則將乙之空白背書欄位中被背書人處填載戊之名而將票據交付予戊，戊再將票 據以記名背書方式交付予己，己於到期日前向A 為承兌之提示，遭A 拒絕，己得對下列何人行使追 索權？','僅甲、乙、丙','僅甲、乙、丁','僅甲、乙、戊','甲、乙、丙、丁、戊','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-031','111-4301',31,'single_choice','甲簽發匯票一紙予乙，付款人為丙，當事人並請丙簽名於票據正面以為憑證。乙將票據背書轉讓予 丁，下列敘述，何者正確？','甲票據責任未定','若丁到期不獲付款，僅得向乙行使追索權','因甲為發票人，故丙之簽名無意義，無須負票據責任','丙應負承兌人責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-032','111-4301',32,'single_choice','A 簽發匯票予B，票據依序背書轉讓予C、D、E，最後由E 背書轉讓予F。F 得行使追索權時，甲、 乙、丙、丁依序願分別為A、B、C、D 參加付款。依票據法，應由何人參加付款？','甲','乙','丙','丁','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-033','111-4301',33,'single_choice','甲於民國（下同）105 年10 月1 日簽發本票一紙給乙，並記載見票後1 個月付款，乙於105 年11 月 1 日再將該票據背書轉讓給丙，丙於106 年4 月30 日持票向甲提示見票，下列敘述，何者正確？','丙逾越見票之提示期限，故丙對甲喪失票據權利','丙未逾越見票之提示期限，故丙可以直接向甲、乙行使追索權','丙逾越見票之提示期限，故丙對甲、乙喪失票據權利','丙逾越見票之提示期限，故丙對乙喪失票據權利，但仍可對甲行使票據權利','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-034','111-4301',34,'single_choice','甲簽發匯票一紙，記載文字金額「新臺幣伍萬元整」及號碼「$60,000 元」，該匯票之票據金額應為 下列何者？','票據無效','$60,000 元','新臺幣伍萬元整','新臺幣伍萬元或$60,000 元均為有效','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-035','111-4301',35,'single_choice','甲授權乙簽發一紙面額新臺幣50 萬元之本票，然乙代理簽發時卻僅於票據上簽自己之名。下列敘述， 何者正確？','只要甲承認乙為其代理人，乙即不負票據責任','乙須自負發票人之責任','甲與乙須連帶負發票人責任','甲因並未簽名，乙並非發票人，故兩人均不負責','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-036','111-4301',36,'single_choice','具股權性質之虛擬通貨（Securities Token Offering）業經主管機關核定為有價證券，下列何者非認定 該通貨之認定標準？','出資於一共同事業','出資人有獲取利潤之期待','利潤主要取決於發行人或第三人之努力','發行人出具書面獲利保證','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('111-4301-037','111-4301',37,'single_choice','A 公司為一家從事航運的上櫃公司，今該公司擬現金發行新股，依證券交易法第28 條之1 規定，下 列敘述何者錯誤？','A 公司若有主管機關認為無須或不適宜對外公開發行者，得不提撥發行新股總額之一定比率，對 外公開發行','主管機關得規定A 公司提撥發行新股總額之一定比率，以時價向外公開發行','A 公司股東會得決議就此次發行新股總額之百分之十二，對外公開發行','A 公司依規定提撥向外公開發行時，同次發行由公司員工承購之價格，應與向外公開發行之價格 相同','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('111-4301-038','111-4301',38,'single_choice','A 上市公司依法設有審計委員會。近期，A 公司擬召開審計委員會，討論該公司內部控制制度修正 案。若A 公司審計委員會欲通過此內部控制制度修正案，應經下列何者之決議通過？','審計委員會全體成員二分之一以上同意','應由三分之二以上審計委員會成員之出席，及出席成員過半數之同意','應有過半數審計委員會成員之出席，出席成員過半數同意','審計委員會全體成員三分之二以上同意','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('111-4301-039','111-4301',39,'single_choice','從事工具機製造之A 股份有限公司已登錄興櫃，資本額新臺幣3 億元，最近一次全面改選董事為民 國109 年，有關該公司之敘述，下列何者錯誤？','應設置獨立董事','應設置薪資報酬委員會','若已設薪資報酬委員會，應由全體獨立董事擔任委員','若已設薪資報酬委員會，其職掌包括審議給付經理人之股票選擇權','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('111-4301-040','111-4301',40,'single_choice','A 公司已持有B 公開發行公司百分之六十一的股權。今A 公司擬以公開收購方式，再取得B 公司百 分之三十的股權。依證券交易法之規定，下列敘述何者錯誤？','A 公司必須向主管機關申報後，始得對B 公司進行公開收購','A 公司於公開收購期間不得於集中交易市場、證券商營業處所、其他任何場所或以其他方式，購 買同種類之B 公司有價證券','A 公司進行公開收購後，原則上不得任意停止公開收購之進行','若A 公司未於收購期間完成預定收購數量，除有正當理由並經主管機關核准者外，A 公司於1 年 內不得再對B 公司進行公開收購','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('111-4301-041','111-4301',41,'single_choice','A 上市公司（下稱A 公司）董事長因為股市連日不正常下跌，為了維護公司信用及股東權益，擬經 A 公司之董事會特別決議，進行買回庫藏股，來維護A 公司之信用及股東權益。依照證券交易法之 規定，下列敘述何者錯誤？','A 公司買回股份之數量比例，不得超過該公司已發行股份總數百分之十，且收買股份之總金額， 不得逾保留盈餘加發行股份溢價及已實現之資本公積之金額','A 公司所進行庫藏股買回，最長可於買回之日起5 年內將其轉讓','A 公司依照規定買回之股份，不得質押，於未轉讓前，不得享有股東權利','A 公司進行庫藏股買回，A 公司之關係企業或董事、監察人、經理人、持有該公司股份超過股份 總額百分之十之股東所持有之股份，於該公司買回之期間內不得賣出','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('111-4301-042','111-4301',42,'single_choice','A 上市公司為避免股本膨脹，原股東股權被稀釋，擬私募普通公司債，以快速取得資金並降低籌資成 本，關於普通公司債之私募，下列敘述何者錯誤？','A 公司須經公司股東會已發行股份總數過半數股東之出席，出席股東表決權三分之二以上之同意， 始得為之','普通公司債之私募，其發行總額除經主管機關徵詢目的事業中央主管機關同意者外，不得逾A 公 司全部資產減去全部負債餘額之400%','A 公司得於董事會決議之日起一年內分次辦理','A 公司應於公司債價款繳納完成日起15 日內，檢附相關書件，報請主管機關備查','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('111-4301-043','111-4301',43,'single_choice','甲請教乙律師，因為在證券市場之運作，證券交易所扮演不可或缺之角色，而證券交易所之組織，通 常分為會員制及公司制，各依照不同制度，有所相應的規範。依照證券交易法之規定，下列敘述何者 錯誤？','證券商之董事、監察人、股東或受僱人不得為公司制證券交易所之經理人','公司制證券交易所之組織，以股份有限公司或有限公司為限','公司制證券交易所發行之股票，不得於自己或他人開設之有價證券集中交易市場，上市交易','公司制證券交易所不得發行無記名股票','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('111-4301-044','111-4301',44,'single_choice','A 公司為一家從事食品加工的股份有限公司，該公司之股票在集中交易市場掛牌交易。依證券交易 法之規定，A 公司第三季的財務報告，除情形特殊，經主管機關另予規定者外，至遲應於每會計年度 第三季終了後幾日內，公告並申報由董事長、經理人及會計主管簽名或蓋章，並經會計師核閱及提報 董事會之財務報告？','10 日','15 日','30 日','45 日','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('111-4301-045','111-4301',45,'single_choice','股票上櫃之B 股份有限公司（下稱B 公司）董事甲，知悉足以影響B 公司股價之消息，於該消息公 開前，以每股50 元買進該公司股票10,000 股，於消息公開後翌日，以每股65 元賣出5,000 股，其 餘5,000 股迄今持有，該消息公開後10 個營業日，B 公司股價平均收盤價為80 元。若甲買賣B 公司 股票之行為遭法院認定為內線交易，若不計算稅與交易手續費，依最高法院大法庭之見解，甲從事內 線交易之犯罪所得為何？','75,000 元','150,000 元','225,000 元','300,000 元','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('111-4301-046','111-4301',46,'single_choice','債權人甲對債務人乙取得清償借款新臺幣100 萬元之確定判決後，免除乙之債務，嗣甲復持該確定 判決聲請臺灣臺中地方法院民事執行處（下稱臺中地院）對乙為強制執行。臺中地院以甲之執行名義 所表彰之實體上請求權，已因免除債務而不存在，乃裁定駁回甲強制執行之聲請。甲於法定期間內向 臺灣高等法院臺中分院（下稱臺中高分院）提起抗告。下列敘述，何者正確？','臺中高分院應以臺中地院之裁定不得聲明不服為由，裁定駁回甲之抗告','臺中高分院應以臺中地院之裁定並無不當為由，裁定駁回甲之抗告','臺中高分院應以甲之抗告為有理由，廢棄臺中地院之裁定，另為諭知准許甲強制執行之聲請','臺中高分院應以甲之抗告為有理由，廢棄臺中地院之裁定，發回臺中地院更為適法之處理','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('111-4301-047','111-4301',47,'single_choice','債權人甲持假扣押裁定，向執行法院聲請執行債務人乙之財產，發現財產不足抵償假扣押債權，甲乃 以乙顯有隱匿財產之情，聲請執行法院定期間命乙據實報告該期間屆滿前1 年間應供強制執行之財 產狀況。執行法院應如何處理？','因甲應就其聲請繳納執行費新臺幣1,000 元，執行法院應定期命其繳納，逾期駁回甲之聲請','因執行債權人有查報債務人財產之義務，甲不得藉此脫免自身義務，執行法院應駁回甲之聲請','因財產不足抵償之債權，係指執行名義命債務人為清償而得終局執行者，假扣押裁定之債權尚未確 定，執行法院應駁回甲之聲請','執行債權無論是否為終局執行之確定債權，執行債權人均得依債務人財產開示之規定，聲請執行法 院命債務人報告其財產狀況，執行法院應准許甲之聲請','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('111-4301-048','111-4301',48,'single_choice','債權人甲持金錢債權執行名義聲請法院就債務人乙所有之A 地為強制執行，法院於110 年3 月1 日 執行查封時，發現乙已於109 年10 月1 日將A 地出租予丙，由丙在該地種植鳳梨。下列敘述，何者 正確？','法院查封A 地之效力，並不及於丙在該土地上所種植之鳳梨','丙就A 地上之鳳梨有收取權，得據以提起第三人異議之訴，以排除法院就鳳梨部分之強制執行','法院查封A 地之效力，應及於查封後乙得向丙收取租金之債權','甲不得併聲請法院就乙所得向丙收取租金之債權，發扣押命令、收取命令而為執行','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('111-4301-049','111-4301',49,'single_choice','債務人甲向債權人乙借款新臺幣（下同）600 萬元，並將甲所有之A 地設定抵押權予乙，以為該借款 債務之擔保，屆期甲未清償，乙取得拍賣抵押物之裁定後，持向法院聲請強制執行，法院於109 年9 月10 日執行查封時，發現甲已於抵押權設定後之108 年10 月1 日，將A 地出租予丙使用，租期4 年。A 地經法院公告拍賣三次始終無人應買，法院乃於110 年7 月14 日公告願買受該地者，得於公 告之日起3 個月內依原定拍賣條件（A 地拍賣之底價為500 萬元）為應買之表示，於尚未有人表示 應買之際，乙於110 年7 月25 日向法院聲請停止公告應買，並聲請法院裁定除去甲丙間之租賃關係 再為減價拍賣，經法院裁定除去該租賃關係後，於110 年8 月30 日進行第四次拍賣程序，該次拍賣 由出價最高之丁以550 萬元得標，出價次高之戊（以500 萬元投標）並未得標，然丁除於投標時繳 納保證金100 萬元外，並未繳清尾款，法院遂於110 年11 月5 日再次進行第四次拍賣程序，惟此次 拍賣並無任何人前來投標應買，乙亦不願承受該地。下列敘述，何者正確？','法院進行第四次拍賣時，就拍賣條件應為拍定後不點交','丁於得標後不願繳清尾款時，法院得依職權宣告改由戊以500 萬元得標','於110 年11 月5 日拍賣期日終結後，應視為乙撤回對於A 地之執行','甲丙間之租賃關係既經法院裁定除去，乙嗣於110 年12 月15 日再次聲請對A 地為強制執行，法 院於第一次拍賣時，拍賣條件應為拍定後點交','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('111-4301-050','111-4301',50,'single_choice','甲分別向乙、丙、丁、戊借貸，並分別簽發及交付本票，作為清償方法，另將其所有之A 地設定抵 押權登記予乙，以擔保乙之債權。上述本票均已到期而經提示未獲兌現，丙及丁各取得本票准予強制 執行之裁定，丙持以聲請法院查封拍賣A 地。在上述情形，得聲明參與分配之債權人，下列敘述， 何者正確？','乙、丁、戊均可','乙、丁可，戊不可','丁可，乙、戊不可','乙、丁、戊均不可','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('111-4301-051','111-4301',51,'single_choice','甲簽發本票向乙借款。乙執該本票聲請法院裁定准許強制執行後，持之聲請執行法院對甲為強制執 行，查封甲之船舶及建造中船舶多艘。有關執行程序，下列敘述，何者正確？','皆準用對於不動產執行之規定','建造完成部分，準用對於不動產執行之規定；建造中部分，依對於動產執行之規定','跨洲航行之20 萬噸郵輪，準用對於不動產執行之規定；日月潭之15 噸觀光船，依對於動產執行 之規定','皆依關於動產執行之規定','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('111-4301-052','111-4301',52,'single_choice','甲主張其向乙購買A 屋後，乙拒絕辦理房屋所有權移轉登記，起訴請求法院判決命乙將該屋所有權 移轉登記予甲，並獲勝訴判決確定。下列敘述，何者正確？','甲為執行該確定判決，得聲請執行法院函該管地政機關辦理A 屋所有權移轉登記','甲得單獨持該確定判決，申請該管地政機關辦理A 屋所有權移轉登記，不必對乙聲請強制執行','乙於甲向地政機關辦理A 屋所有權移轉登記前，仍得聲請停止執行','如確定判決命乙於甲給付全部價金之同時應將A 屋所有權移轉登記予甲，乙就該價金得持該判決 為執行名義聲請對甲為強制執行','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('111-4301-053','111-4301',53,'single_choice','甲、乙、丙分別共有A、B 二筆土地，甲列乙、丙為被告，訴請法院裁判分割A、B 土地，法院以判 決諭知A 土地應變賣分割，B 土地應原物分割為B1、B2、B3 三部分，依序分歸甲、乙、丙單獨取 得，並告確定。下列敘述，何者錯誤？','丙為該判決之被告，不得持該判決聲請強制執行','甲持該判決聲請強制執行，A 土地經二次減價拍賣無人應買，甲、乙、丙不願承受，甲未撤回A 土 地之執行，執行法院得繼續拍賣A 土地至拍定為止','甲、乙、丙不必經強制執行，已分別取得B1、B2、B3 土地之所有權','甲持該判決聲請強制執行，執行法院得依甲之聲請點交B1 土地','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('111-4301-054','111-4301',54,'single_choice','甲向乙購買乙所有之A 地後，發現乙一地二賣，乃向法院聲請禁止乙移轉A 地所有權之假處分，並 經法院裁定准許。下列敘述，何者錯誤？','如甲未對乙提起請求移轉A 地所有權之訴，為假處分裁定之法院，應依乙之聲請，命甲於一定期 間起訴','法院應於假處分裁定執行後，始將該裁定送達乙','甲收受假處分裁定後，逾30 日時，不得聲請假處分之執行','如丙已基於其對A 地之地上權，起訴請求乙交付A 地，並獲得勝訴判決確定，執以聲請強制執行 時，法院應駁回甲對乙就A 地所為禁止移轉之假處分執行聲請','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('111-4301-055','111-4301',55,'single_choice','債權人甲持和解筆錄，聲請執行法院對乙為強制執行，請求拍賣乙之A 土地，償還乙積欠甲之新臺 幣（下同）1,000 萬元。債權人丙持假扣押裁定，於A 土地遭查封之翌日聲請執行法院對乙為強制執 行，亦請求查封A 土地，保全丙對乙之1,200 萬元債權。下列敘述，何者正確？','終局執行優先於保全執行，執行法院應裁定駁回丙之強制執行聲請','保全執行優先於終局執行，執行法院應裁定駁回甲之強制執行聲請','執行法院應立即囑託地政機關就A 土地再為假扣押查封登記，防免甲撤回強制執行聲請時，乙趁 機脫產','丙之強制執行聲請，為已實施執行行為之效力所及，執行法院不須再查封A 土地','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('111-4301-056','111-4301',56,'single_choice','Eric was next door to Ben. Eric decided to build a new swimming pool in his backyard. After the construction was done, Ben found the pool was partly built on his land. It is a if Eric intentionally built his pool on other’s land.','trespass','battery','assault','misrepresentation','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-057','111-4301',57,'single_choice','Which of the following is not a sub-field of the law of torts in American common law?','medical malpractice','products liability','auto accidents','devolution of property','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-058','111-4301',58,'single_choice','When the director and the corporation are both parties to a transaction which involves a director''s conflicting interests. The director cannot participate in the corporate decision-making process that approves the transaction in order to avoid violating the to the corporation.','duty of care','duty of loyalty','duty of reliance','duty of good deed','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-059','111-4301',59,'single_choice','If a Supreme Court Justice agrees with the outcome of the case, but not the majority’s rationale for it, that Justice may write a opinion.','dissenting','majority','plurality','concurring','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-060','111-4301',60,'single_choice','Mary tried to collect on an airline trip insurance policy she had purchased, but was refused by the insurance company on the ground that the policy applied only to a trip on “scheduled airline” and that “technically” under some obscure regulations Mary’s flight was not “scheduled,” even though she had every reason to believe that it was. The court held in favor of Mary on the ground that ordinary insurance buyer’s understanding should apply, since this was a contract .','of beneficence','of adhesion','for deed','under seal','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-061','111-4301',61,'single_choice','Sean submitted and Rene accepted a bid to supply approximately 4,000 tons of trap rock for an airport at a unit price. The parties executed a standard form of “Invitation, Bid, and Acceptance (Short From Contract)” supplied by Rene, including typed terms “to be delivered to project as required,” “delivery to start immediately,” and “cancellation by Rene may be effected at any time.” However, requires that Rene orders and accepts the rock within a reasonable time unless Rene has given Sean a notice of intent to cancel.','good faith','good feeling','good intent','good will','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('111-4301-062','111-4301',62,'single_choice','Securities law intervenes in corporate governance in several ways. From the example of Taiwan’s securities law, which of the following does not reflect this intervention?','Companies cannot solicit and receive proxy from shareholders freely.','Companies need to make a public financial disclosure every season or year.','A certain number of independent directors are required for newly listed companies.','When issuing new stock, participating underwriters need to have licenses, meet strict qualifications, and cannot be bypassed.','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
